// Daftar permintaan BPS: 3 indikator (var id) — samakan dengan /data/region-mapping.ts.
// BPS_API_KEY diambil dari env n8n (set di instance: BPS_API_KEY=...).
const key = $env.BPS_API_KEY;
if (!key) throw new Error('Env BPS_API_KEY belum di-set di instance n8n');
const VARS = [
  { indikator: 'ipm', varId: 414, clamp: [40, 95] },
  { indikator: 'gini_ratio', varId: 370, clamp: [0.2, 0.6] },
  { indikator: 'tingkat_pengangguran', varId: 543, clamp: [1, 20] },
];
return VARS.map(v => ({ json: { ...v, url: `https://webapi.bps.go.id/v1/api/list/model/data/domain/0000/var/${v.varId}/key/${key}/` } }));

// Transformasi fiksi deterministik — port dari /lib/bps-transform.ts (jaga sinkron!).
const MAPPINGS = [
  { regionCode: 'candrakala', prov: '31' },
  { regionCode: 'lembah_sarna', prov: '33' },
  { regionCode: 'kutabara', prov: '64' },
  { regionCode: 'tirtagati', prov: '71' },
  { regionCode: 'argasoka', prov: '34' },
];
function hashString(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193);}return h>>>0;}
function mulberry32(seed){let a=seed>>>0;return()=>{a|=0;a=(a+0x6d2b79f5)|0;let t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function noiseMult(key){const rng=mulberry32(hashString(key));const mag=0.05+rng()*0.10;const sign=rng()<0.5?-1:1;return 1+sign*mag;}
function transform(value, regionCode, indikator, periode, clamp){const noisy=value*noiseMult(`${regionCode}|${indikator}|${periode}`);const v=Math.min(clamp[1],Math.max(clamp[0],noisy));return Math.round(v*100)/100;}

const regionPatches = {}; const rawRows = [];
// $input.all() berisi respons BPS berurutan sesuai item 'Daftar Indikator'
const reqs = $('Daftar Indikator').all();
const resps = $input.all();
for (let i = 0; i < resps.length; i++) {
  const meta = reqs[i].json;
  const body = resps[i].json;
  if (!body || body.status !== 'OK' || !body.datacontent) continue;
  const vervar = body.vervar || []; const tahun = (body.tahun || []).slice().sort((a,b)=>Number(b.val)-Number(a.val));
  const turvar = body.turvar?.[0]?.val ?? 0; const turth = body.turtahun?.[0]?.val ?? 0;
  for (const m of MAPPINGS) {
    const wilayah = vervar.find(v => String(v.val).startsWith(m.prov));
    if (!wilayah) continue;
    let found = null;
    for (const th of tahun) {
      const key = `${wilayah.val}${meta.varId}${turvar}${th.val}${turth}`;
      const nilai = body.datacontent[key];
      if (typeof nilai === 'number' && isFinite(nilai)) { found = { nilai, periode: String(th.label ?? th.val) }; break; }
    }
    if (!found) continue;
    rawRows.push({ indikator: meta.indikator, wilayah_sumber: m.prov + '00', nilai: found.nilai, periode: found.periode });
    regionPatches[m.regionCode] = regionPatches[m.regionCode] || {};
    regionPatches[m.regionCode][meta.indikator] = transform(found.nilai, m.regionCode, meta.indikator, found.periode, meta.clamp);
  }
}
return Object.entries(regionPatches).map(([code, patch]) => ({ json: { region_code: code, patch: { ...patch, source_updated_at: new Date().toISOString() }, raw: rawRows } }));
